/**
 * @name Path traversal in importlib_metadata
 * @description Reading files with user-controlled paths could lead to path traversal attacks
 * @kind path-problem
 * @problem.severity high
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(FileSystemAccess fa |
      sink = fa.getAPathArgument()
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name XML parsing vulnerabilities in importlib_metadata
 * @description Parsing XML from untrusted sources can lead to XXE attacks
 * @kind path-problem
 * @problem.severity high
 * @id py/xxe
 * @tags security
 *        external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module XXEConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("xml").getMember(["etree", "dom", "sax", "ElementTree"]).getMember("*").getACall() and
      sink = call.getArg(0)
    )
  }
}

module XXEFlow = TaintTracking::Global<XXEConfig>;
import XXEFlow::PathGraph

from XXEFlow::PathNode source, XXEFlow::PathNode sink
where XXEFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XML parsing from untrusted source $@.", source.getNode(), "user input"
